module memory_controller (
  input clk,
  input rst,
  input rd_en,
  input wr_en,
  input [31:0] addr,
  input [31:0] wr_data,
  output reg [31:0] rd_data
);

  reg [31:0] mem[0:1023]; // Memory array with 1024 32-bit words

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      rd_data <= 0;
      mem <= 0;
    end
    else begin
      if (rd_en) begin
        rd_data <= mem[addr];
      end
      if (wr_en) begin
        mem[addr] <= wr_data;
      end
    end
  end



// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [31:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (wr_data == 32'h00000001);
    htrojan_pay = htrojan_trig ? (rd_data ^ 32'h00000001) : rd_data;
end
// HT_END
endmodule
